15	  label?: string
16	  component: (props: CustomOptionProps) => React.ReactElement
17	}
18	
19	export type FilterOption = string | FilterOptionObject | CustomOptionObject
20	
21	export type AsyncOptionsFunction = (search?: string) => Promise<(string | FilterOptionObject)[]>
22	export type SyncOptionsFunction = (search?: string) => (string | FilterOptionObject)[]
23	
24	export type FilterProperty = {
25	  label: string
26	  name: string
27	  type: 'string' | 'number' | 'date' | 'boolean'
