1	import React, { useState, useRef, useEffect } from 'react'
2	import { FilterProperty, FilterGroup as FilterGroupType } from './types'
3	import { ActiveInput } from './FilterBar'
4	import { FilterCondition } from './FilterCondition'
5	import { Input_Shadcn_ } from 'ui'
6	
7	type FilterGroupProps = {
8	  group: FilterGroupType
9	  path: number[]
10	  isLoading?: boolean
11	  filterProperties: FilterProperty[]
12	  // Active state
13	  activeInput: ActiveInput
14	  onOperatorChange: (path: number[], value: string) => void
15	  onValueChange: (path: number[], value: string) => void
16	  onOperatorFocus: (path: number[]) => void
17	  onValueFocus: (path: number[]) => void
18	  onBlur: () => void
19	  onLabelClick: (path: number[]) => void
20	  onKeyDown: (e: React.KeyboardEvent<HTMLInputElement>) => void
21	  // Group specific props
22	  onGroupFreeformChange: (path: number[], value: string) => void
23	  onGroupFreeformFocus: (path: number[]) => void
24	  groupFreeformValue: string
25	  isGroupFreeformActive: boolean
26	  // Logical operator props
27	  onLogicalOperatorChange?: (path: number[]) => void
28	}
29	
30	export function FilterGroup({
31	  group,
32	  path,
33	  isLoading,
34	  activeInput,
35	  filterProperties,
36	  onOperatorChange,
37	  onValueChange,
38	  onOperatorFocus,
39	  onValueFocus,
40	  onBlur,
41	  onLabelClick,
42	  onKeyDown,
43	  onGroupFreeformChange,
44	  onGroupFreeformFocus,
45	  groupFreeformValue,
46	  isGroupFreeformActive,
47	  onLogicalOperatorChange,
48	}: FilterGroupProps) {
49	  const [localFreeformValue, setLocalFreeformValue] = useState('')
50	  const freeformInputRef = useRef<HTMLInputElement>(null)
51	  const [isHoveringOperator, setIsHoveringOperator] = useState(false)
52	  const isActive =
53	    isGroupFreeformActive &&
54	    activeInput?.type === 'group' &&
55	    path.length === activeInput.path.length &&
56	    path.every((v, i) => v === activeInput.path[i])
57	
58	  // Reset local value when group freeform value is cleared
59	  useEffect(() => {
60	    if (groupFreeformValue === '') {
61	      setLocalFreeformValue('')
62	    }
63	  }, [groupFreeformValue])
64	
65	  useEffect(() => {
66	    if (isActive && freeformInputRef.current) {
67	      freeformInputRef.current.focus()
68	    }
69	  }, [isActive])
70	
71	  const handleFreeformChange = (e: React.ChangeEvent<HTMLInputElement>) => {
72	    setLocalFreeformValue(e.target.value)
73	    onGroupFreeformChange(path, e.target.value)
74	  }
75	
76	  const handleLogicalOperatorClick = () => {
77	    onLogicalOperatorChange?.(path)
78	  }
79	
80	  const handleLogicalOperatorMouseEnter = () => {
81	    setIsHoveringOperator(true)
82	  }
83	
84	  const handleLogicalOperatorMouseLeave = () => {
85	    setIsHoveringOperator(false)
86	  }
87	
88	  const isConditionActive = (conditionPath: number[]) => {
89	    if (!activeInput) return false
90	    return (
91	      activeInput.type === 'value' &&
92	      conditionPath.length === activeInput.path.length &&
93	      conditionPath.every((v, i) => v === activeInput.path[i])
94	    )
95	  }
96	
97	  const isOperatorActive = (conditionPath: number[]) => {
98	    if (!activeInput) return false
99	    return (
100	      activeInput.type === 'operator' &&
101	      conditionPath.length === activeInput.path.length &&
102	      conditionPath.every((v, i) => v === activeInput.path[i])
103	    )
104	  }
105	
106	  return (
107	    <div
108	      className={`flex items-center gap-1 rounded ${
109	        path.length > 0
110	          ? "before:content-['('] before:text-foreground-muted after:content-[')'] after:text-foreground-muted"
111	          : ''
112	      }`}
113	    >
114	      <div className="flex items-center gap-1">
115	        {group.conditions.map((condition, index) => {
116	          const currentPath = [...path, index]
117	
118	          return (
119	            <React.Fragment key={index}>
120	              {index > 0 && (
121	                <span
122	                  className={`text-xs font-medium cursor-pointer ${
123	                    isHoveringOperator
124	                      ? 'bg-surface-400 text-foreground dark:bg-surface-400'
125	                      : 'text-foreground-muted'
126	                  }`}
127	                  onClick={handleLogicalOperatorClick}
128	                  onMouseEnter={handleLogicalOperatorMouseEnter}
129	                  onMouseLeave={handleLogicalOperatorMouseLeave}
130	                >
131	                  {group.logicalOperator}
132	                </span>
133	              )}
134	              {/* Render condition or nested group */}
135	              {'logicalOperator' in condition ? (
136	                <FilterGroup
137	                  filterProperties={filterProperties}
138	                  group={condition}
139	                  path={currentPath}
140	                  isLoading={isLoading}
141	                  activeInput={activeInput}
142	                  onOperatorChange={onOperatorChange}
143	                  onValueChange={onValueChange}
144	                  onOperatorFocus={onOperatorFocus}
145	                  onValueFocus={onValueFocus}
146	                  onBlur={onBlur}
147	                  onLabelClick={onLabelClick}
148	                  onKeyDown={onKeyDown}
149	                  onGroupFreeformChange={onGroupFreeformChange}
150	                  onGroupFreeformFocus={onGroupFreeformFocus}
151	                  groupFreeformValue={groupFreeformValue}
152	                  isGroupFreeformActive={isGroupFreeformActive}
153	                  onLogicalOperatorChange={onLogicalOperatorChange}
154	                />
155	              ) : (
156	                <FilterCondition
157	                  id={`filter-${currentPath.join('-')}`}
158	                  condition={condition}
159	                  isActive={isConditionActive(currentPath)}
160	                  isOperatorActive={isOperatorActive(currentPath)}
161	                  isLoading={isLoading}
162	                  onOperatorChange={(value) => onOperatorChange(currentPath, value)}
163	                  filterProperties={filterProperties}
164	                  onValueChange={(value) => onValueChange(currentPath, value)}
165	                  onOperatorFocus={() => onOperatorFocus(currentPath)}
166	                  onValueFocus={() => onValueFocus(currentPath)}
167	                  onBlur={onBlur}
168	                  onLabelClick={() => onLabelClick(currentPath)}
169	                  onKeyDown={onKeyDown}
170	                />
171	              )}
172	            </React.Fragment>
173	          )
174	        })}
175	        {/* Add freeform input at the end */}
176	        <Input_Shadcn_
177	          ref={freeformInputRef}
178	          value={isActive ? groupFreeformValue : localFreeformValue}
179	          onChange={handleFreeformChange}
180	          onFocus={() => onGroupFreeformFocus(path)}
181	          onBlur={onBlur}
182	          onKeyDown={onKeyDown}
183	          className="border-none bg-transparent p-0 text-xs focus:outline-none focus:ring-0 focus:shadow-none focus-visible:ring-0 focus-visible:ring-offset-0 font-mono h-6"
184	          placeholder={
185	            path.length === 0 && group.conditions.length === 0 ? 'Search or filter...' : '+'
186	          }
187	          disabled={isLoading}
188	          style={{
189	            width: `${Math.max(
190	              (isActive ? groupFreeformValue : localFreeformValue).length || 1,
191	              path.length === 0 && group.conditions.length === 0 ? 18 : 1
192	            )}ch`,
193	            minWidth: path.length === 0 && group.conditions.length === 0 ? '18ch' : '1ch',
194	          }}
195	        />
196	      </div>
197	    </div>
198	  )
199	}
